<template>
 <el-dialog :model-value="!!runId" title="回答反馈详情" width="920px" class="ej-dialog feedback-detail-dialog" append-to-body :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving" @update:model-value="!$event && emit('close')">
  <ContentState v-if="loading" kind="loading" title="正在读取反馈详情" /><ContentState v-else-if="loadError" kind="error" title="反馈详情暂时无法加载" :description="loadError" @retry="load" />
  <div v-else-if="detail" class="feedback-detail">
   <div class="feedback-run-meta"><code>{{ detail.feedback.run_id }}</code><span>{{ statusLabel(detail.feedback.run_status) }}</span><span>{{ detail.feedback.review_state==='resolved'?'已解决':'待处理' }}</span></div>
   <section><h3>用户补充说明</h3><p class="feedback-comment-text">{{ detail.feedback.comment || '未填写补充说明' }}</p></section>
   <p v-if="detail.feedback.conversation_status!==1" class="feedback-detail-note">这段会话已删除，问答内容不再展示。</p>
   <section v-for="turn in turns" :key="turn.label"><h3>{{ turn.label }}</h3><div v-if="turn.value" class="feedback-detail-text" v-html="render(turn.value.content)"></div><p v-else class="feedback-detail-note">{{ turn.label==='原始问题'?'该运行缺少问题关联记录，无法准确定位原始问题。':'没有可读取的回答记录。' }}</p><p v-if="turn.value?.truncated" class="feedback-detail-note">内容较长，此处显示前 100000 字。</p></section>
   <details><summary>执行过程 · 最近 {{ detail.events.length }} 条记录</summary><div class="feedback-events"><table><thead><tr><th>环节</th><th>状态</th><th>耗时</th></tr></thead><tbody><tr v-for="event in detail.events" :key="event.event_id"><td>{{ stageLabel(event.node) }}</td><td>{{ statusLabel(event.status) }}</td><td>{{ event.duration_ms==null?'—':event.duration_ms+' ms' }}</td></tr></tbody></table><p v-if="!detail.events.length" class="feedback-detail-note">暂无执行记录</p></div></details>
   <section v-if="canManage" class="feedback-review-form"><h3>处理反馈</h3><label>处理状态<AppSelect v-model="state" :disabled="saving"><AppSelectOption value="pending">待处理</AppSelectOption><AppSelectOption value="resolved">已解决</AppSelectOption></AppSelect></label><label>处理说明<textarea v-model="note" :disabled="saving" rows="3" maxlength="1000" placeholder="说明问题原因、改动或核查结果；标记已解决时必填。" /></label><p v-if="saveError" role="alert" class="feedback-save-error">{{ saveError }}<button v-if="conflict" type="button" :disabled="saving" @click="load">重新读取最新反馈</button></p></section>
   <section v-else-if="detail.feedback.review_note"><h3>处理说明</h3><p class="feedback-comment-text">{{ detail.feedback.review_note }}</p></section>
   <details v-if="detail.history.length"><summary>处理记录 · 最近 {{ detail.history.length }} 次</summary><ol class="feedback-review-history"><li v-for="(entry,index) in detail.history" :key="index"><strong>{{ entry.to_state==='resolved'?'已解决':'待处理' }}</strong><small>{{ time(entry.created_at) }} · 操作人 {{ entry.actor_id }}</small><p>{{ entry.note || '未填写说明' }}</p></li></ol></details>
  </div>
  <template #footer><button type="button" class="feedback-detail-close" :disabled="saving" @click="emit('close')">关闭</button><button v-if="detail && !loading && !loadError && canManage" type="button" class="feedback-detail-save" :disabled="saving || conflict || state==='resolved'&&!note.trim()" @click="save">{{ saving?'正在保存…':'保存处理结果' }}</button></template>
 </el-dialog>
</template>
<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import request from '@/utils/request'
import {latestRequest} from '@/utils/latestRequest'
import {safeHtml} from '@/utils/safeHtml'
import {renderChatMarkdown} from '@/utils/chatMarkdown'
import {errorMessage} from '@/utils/feedback'
import ContentState from './ContentState.vue'
const props=defineProps<{runId:string;canManage:boolean}>(),emit=defineEmits<{close:[];updated:[]}>()
const detail=ref<any>(),loading=ref(false),loadError=ref(''),saving=ref(false),saveError=ref(''),state=ref('pending'),note=ref(''),conflict=ref(false),gate=latestRequest()
let command={key:'',id:''}
const turns=computed(()=>[{label:'原始问题',value:detail.value?.question},{label:'实际回答',value:detail.value?.answer}])
const render=(text:string)=>safeHtml(renderChatMarkdown(text||''))
const time=(value:string)=>value?.replace('T',' ').slice(0,19)
const statusLabel=(value:string)=>({succeeded:'成功',complete:'完成',completed:'完成',started:'开始',running:'执行中',failed:'失败',degraded:'降级完成',cancelled:'已停止',pending:'待处理'}[value]||value)
const stageLabel=(value:string)=>({main_agent:'Main 决策',main_retrieve:'资料检索',main_delegate:'任务委派',main_answer:'生成回答',final_gate:'交付核验',generate_draft:'生成草稿',save_draft:'保存草稿'}[value]||value)
async function load(){if(!props.runId)return;const ticket=gate.begin();loading.value=true;loadError.value='';saveError.value='';conflict.value=false;try{const r:any=await request.get(`/admin/agent-feedback/${props.runId}`,{signal:ticket.signal});if(ticket.isCurrent()){detail.value=r.data;state.value=r.data.feedback.review_state;note.value=r.data.feedback.review_note||'';command={key:'',id:''}}}catch(e){if(ticket.isCurrent())loadError.value=errorMessage(e,'读取反馈详情失败')}finally{if(ticket.isCurrent())loading.value=false}}
async function save(){if(saving.value||!detail.value||conflict.value)return;const id=props.runId,body={state:state.value,note:note.value,version:detail.value.feedback.review_version,generation:detail.value.feedback.feedback_generation};const key=JSON.stringify({id,...body});if(command.key!==key)command={key,id:crypto.randomUUID()};saving.value=true;saveError.value='';try{await request.put(`/admin/agent-feedback/${id}/review`,{...body,commandId:command.id});if(props.runId===id){await load();emit('updated')}}catch(e:any){if(props.runId===id){conflict.value=[404,409].includes(Number(e?.code));saveError.value=conflict.value?'反馈已更新或撤回，请重新读取后处理':errorMessage(e,'保存失败，请重试')}}finally{saving.value=false}}
watch(()=>props.runId,id=>{gate.cancel();detail.value=undefined;loadError.value='';saveError.value='';if(id)void load()},{immediate:true});onUnmounted(()=>gate.cancel())
</script>
<style scoped>
.feedback-detail{display:grid;gap:22px;color:var(--ej-ink)}h3{font-size:14px;margin:0 0 10px}.feedback-run-meta{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--ej-muted)}.feedback-run-meta code{overflow-wrap:anywhere}.feedback-comment-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.8;padding:12px;background:var(--ej-canvas);border-radius:10px}.feedback-detail-text{max-height:360px;overflow:auto;border:1px solid var(--ej-line);border-radius:12px;padding:16px;font-size:14px;line-height:1.8;overflow-wrap:anywhere}.feedback-detail-text :deep(pre){overflow:auto;background:var(--code-bg);color:var(--code-text);padding:14px;border-radius:10px}.feedback-detail-text :deep(:is(ul,ol)){padding-left:22px}.feedback-detail-text :deep(:is(p,pre,table,ul,ol)){margin-bottom:12px}.feedback-detail-text :deep(table){display:block;max-width:100%;overflow:auto}.feedback-detail-note{font-size:12px;color:var(--ej-muted);line-height:1.8}.feedback-review-form{display:grid;gap:12px;padding:18px;background:var(--ej-canvas);border-radius:14px}.feedback-review-form label{display:grid;gap:8px;font-size:13px}.feedback-review-form textarea{width:100%;padding:10px 12px;border:1px solid var(--ej-line);border-radius:10px;background:var(--ej-surface);color:var(--ej-ink);font:inherit;resize:vertical}.feedback-review-form .ej-select{max-width:220px}.feedback-save-error{color:#a73f2d;font-size:12px;line-height:1.8}.feedback-save-error button{margin-left:8px}.feedback-detail-close,.feedback-detail-save,.feedback-save-error button{padding:9px 16px;border:1px solid var(--ej-line);border-radius:99px;background:var(--ej-surface);color:var(--ej-ink);font:inherit;font-size:12px;cursor:pointer}.feedback-detail-save{margin-left:10px;background:var(--ej-ink);color:var(--ej-surface)}button:disabled{opacity:.45;cursor:not-allowed}summary{font-size:13px;cursor:pointer}.feedback-events{overflow:auto;margin-top:12px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px;text-align:left;border-bottom:1px solid var(--ej-line);overflow-wrap:anywhere}.feedback-review-history{list-style:none;margin-top:14px;padding:0}.feedback-review-history li{padding:12px 0;border-bottom:1px solid var(--ej-line);font-size:12px}.feedback-review-history small{display:block;color:var(--ej-muted);margin:6px 0}.feedback-review-history p{white-space:pre-wrap;overflow-wrap:anywhere}
</style>
